const r = $input.first().json;

// Fallo de BD: nunca dejar al LLM sin respuesta ni inventar disponibilidad
if (r.error || !r.fecha_consultada) {
  return [{ json: {
    exito: false,
    codigo: 'ERROR_TECNICO',
    mensaje: 'No se pudo consultar la agenda.',
    instruccion_agente: 'NO afirmes ni niegues disponibilidad. Discúlpate, dile al cliente que revisarás y llama escalar_humano.'
  } }];
}

if (!r.servicio) {
  return [{ json: {
    exito: false,
    codigo: 'SERVICIO_NO_ENCONTRADO',
    mensaje: 'No se reconoció el servicio.',
    instruccion_agente: 'Pregunta al cliente qué servicio desea del catálogo y vuelve a consultar con el código correcto.'
  } }];
}

const h12 = (hhmm) => {
  let [h, m] = hhmm.split(':').map(Number);
  const suf = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return `${h}:${String(m).padStart(2, '0')} ${suf}`;
};

const slots = r.slots_24h ? r.slots_24h.split(',').map(h12) : [];

return [{
  json: {
    exito: true,
    servicio: r.servicio,
    duracion_minutos: r.duracion_minutos,
    fecha_consultada: r.fecha_consultada,
    horarios_disponibles: slots,
    instruccion_agente: slots.length
      ? 'Estos son los ÚNICOS horarios libres (inicio del servicio). Si la hora pedida no está en la lista, di que no está libre y ofrece los 2-3 más cercanos. No inventes otros.'
      : 'No hay cupos ese día (domingo, fecha pasada, cerrado o agenda llena). Ofrece otro día.'
  }
}];
